function getLivepersonTranslation(key, lang) {
  if (livepersonTranslations[lang] && livepersonTranslations[lang][key]) {
    return livepersonTranslations[lang][key];
  }
  if (livepersonTranslations.en && livepersonTranslations.en[key]) {
    return livepersonTranslations.en[key];
  }
  return null;
}

function applyLivepersonTranslations(lang) {
  console.log(`🔥 Applying liveperson translations for: ${lang}`);
  let count = 0;
  document.querySelectorAll('[data-i18n]').forEach(element => {
    const key = element.getAttribute('data-i18n');
    if (key && (key.startsWith('review.liveperson.') || key.startsWith('review.common.'))) {
      const translation = getLivepersonTranslation(key, lang);
      if (translation) {
        element.textContent = translation;
        count++;
      }
    }
  });
  console.log(`✅ Applied ${count} liveperson translations`);
}

window.addEventListener('languageChanged', (e) => {
  const lang = e.detail.language;
  setTimeout(() => applyLivepersonTranslations(lang), 200);
});

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyLivepersonTranslations(currentLang);
  });
} else {
  const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
  applyLivepersonTranslations(currentLang);
}

console.log('✅ liveperson i18n loaded');
